{"command": "python3 << 'EOF'
from PIL import Image
im = Image.open('barcode.png').convert('RGB')
W,H = im.size
px = im.load()
cols = []
for x in range(W):
    r=g=b=0
    for y in range(H):
        p=px[x,y]; r+=p[0]; g+=p[1]; b+=p[2]
    cols.append((r/H,g/H,b/H))

def dist(a,b): return max(abs(a[0]-b[0]),abs(a[1]-b[1]),abs(a[2]-b[2]))
# print all column-to-column diffs above small threshold
edges=[]
for x in range(1,W):
    d=dist(cols[x],cols[x-1])
    if d>6:
        edges.append((x,d))
print("num small+ edges:", len(edges))
for x,d in edges:
    print(x, round(d,1), end='  |  ')
print()
EOF"}

